WITH valid AS (SELECT id, product_name, category, brand, price, cost, tags, supplier_id, LEAST(stock_qty, cost) least_stock_qty_cost, SORT_ARRAY(tags) sorted_tags FROM products WHERE launch_date > TO_DATE('2023-04-30') AND cost < 660), with_dims AS (SELECT e.id, e.product_name, e.tags, e.supplier_id, e.sorted_tags, p.city FROM valid e LEFT JOIN suppliers p ON e.supplier_id = p.id), joined AS (SELECT e.id, e.supplier_id, e.sorted_tags, e.city, s.country, s.city AS supplier_city FROM with_dims e LEFT JOIN suppliers s ON e.supplier_id = s.id WHERE s.rating BETWEEN 2.7 AND 3.6), with_dims_products AS (SELECT e.id, e.supplier_id, e.supplier_city, s.city AS supplier_city_2, s.country AS supplier_country, s.supplier_name FROM joined e INNER JOIN suppliers s ON e.supplier_id = s.id), enriched AS (SELECT src.id, src.supplier_id, src.supplier_city, src.supplier_city_2, b.rating, b.country FROM with_dims_products src INNER JOIN suppliers b ON src.supplier_id = b.id), not_flagged AS (SELECT s.* FROM enriched s WHERE NOT EXISTS (SELECT 1 FROM order_items x WHERE x.product_id = s.id AND x.quantity > 5)) SELECT dim.city, src.country AS product_country, COUNT(*) AS cnt, AVG(src.rating) AS avg_rating FROM not_flagged src INNER JOIN suppliers dim ON src.supplier_id = dim.id GROUP BY GROUPING SETS ((dim.city, src.country), (dim.city), ()) ORDER BY city NULLS FIRST;
